import sqlite3; c=sqlite3.connect("data/realtyvoice.db"); print("SOURCE COUNTS:",c.execute("SELECT source_name, COUNT(*) FROM properties GROUP BY source_name").fetchall()); print("TOTAL PROPERTIES:",c.execute("SELECT COUNT(*) FROM properties").fetchone()[0]); print("PUBLIC ROWS WITH AVAILABILITY:",c.execute("SELECT COUNT(*) FROM properties WHERE source_name=? AND availability_status IS NOT NULL",("kaggle_house_price_india",)).fetchone()[0]); print("PUBLIC ROWS WITH POSSESSION DATE:",c.execute("SELECT COUNT(*) FROM properties WHERE source_name=? AND possession_date IS NOT NULL",("kaggle_house_price_india",)).fetchone()[0]); print("INTEGRITY:",c.execute("PRAGMA integrity_check").fetchone()[0]); print("FOREIGN KEY ERRORS:",c.execute("PRAGMA foreign_key_check").fetchall()); c.close()
